-- Dire Maul (map 429), Capital Gardens (west wing), 2026-11-12.
--
-- 1. Mana Burst 14397: six static spawns stood on top of Residual Monstrosities (guids 324130-324135).
--    Mana Bursts are what a Residual Monstrosity summons when it dies (Summon Mana Bursts 22939);
--    the static copies are sniff leftovers (none in the Pandaria 5.4.8 or AzerothCore databases).
-- 2. Movement: the west wing had 2 wanderers out of 268 spawns. Like the Warpwood Quarter
--    (2026_11_03_05): Pandaria 5.4.8 paths for the same guids (15 patrols, paths 429001001+),
--    AzerothCore wander radius matched by entry and position (7 wanderers). Bosses, the Shen'dralar,
--    Lord Hel'nurath and the generator guards' spots are left alone.
-- The shield generators and Immol'thar's force field are handled by tools/bfa/dire-maul-west.patch.

-- 1. Mana Burst sniff leftovers
DELETE FROM `creature_addon` WHERE `guid` IN (324130, 324131, 324132, 324133, 324134, 324135);
DELETE FROM `creature` WHERE `guid` IN (324130, 324131, 324132, 324133, 324134, 324135) AND `id`=14397;

-- 2. Patrols (Pandaria 5.4.8, same guids)
DELETE FROM `waypoint_data` WHERE `id` BETWEEN 429001001 AND 429002000;
ON DUPLICATE KEY UPDATE `path_id`=VALUES(`path_id`);
UPDATE `creature` SET `MovementType`=2, `spawndist`=0 WHERE `guid` IN (323310, 323313, 323317, 323318, 323355, 323356, 323357, 323498, 323511, 323644, 323667, 323780, 323786, 324140, 324144);

-- Random wandering (AzerothCore wander radius)
UPDATE `creature` SET `MovementType`=1, `spawndist`=5 WHERE `MovementType`=0 AND `guid` IN (323330, 323331, 323486, 323666, 323669, 323787, 323859);
